// The slice of @google-cloud/storage's type surface the fixture code
// touches. The recognizer settles a call by where the method is
// declared, so the declarations have to be on disk under node_modules.

export declare class Storage {
  bucket(name: string): Bucket;
}

export declare class Bucket {
  file(path: string): File;
}

export declare class File {
  save(body: string): Promise<void>;
  download(): Promise<[Buffer]>;
}
